set pagesize 200 linesize 200 feedback off
col grantee format a10
col table_name format a24
col privilege format a10
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM DBA_TAB_PRIVS WHERE GRANTEE='PUBLIC' AND TABLE_NAME IN ('UTL_HTTP','UTL_TCP','UTL_SMTP','UTL_FILE','DBMS_SCHEDULER','DBMS_PIPE','UTL_INADDR','DBMS_LDAP','DBMS_JAVA','UTL_MAIL','DBMS_SQL','DBMS_LOB','DBMS_XSLPROCESSOR','DBMS_ADVISOR','DBMS_AQ','HTTPURITYPE','DBMS_NETWORK_ACL_ADMIN','DBMS_CLOUD') ORDER BY 2;
SELECT USERNAME, READ_ONLY FROM DBA_USERS WHERE USERNAME IN ('APP_RO','APP_OWNER');
SELECT COUNT(*) dirs_public FROM DBA_TAB_PRIVS WHERE GRANTEE='PUBLIC' AND TYPE='DIRECTORY';
